# Complete source inventory for the next VM phase, without claiming static scan proves execution.
entries=[]
for p in sorted((root/'zak/converted/scripts_flat').rglob('*.txt')):
 text=p.read_text(encoding='utf8');ops=collections.Counter()
 for line in text.splitlines():
  m=re.match(r'\[[0-9A-F]+\] \([^)]+\) (.*)',line)
  if m:
   ins=m[1];op=re.match(r'(\w+)',ins);ops[op[1] if op else ins]+=1
 entries.append({'source':p.as_posix(),'instructions':sum(ops.values()),'operations':dict(ops)})
(root/'docs/evidence/full-script-inventory.json').write_text(json.dumps(entries,indent=2)+'\n',encoding='utf8')
print('view report:',len(data['rooms']),'source scripts:',len(entries),'instructions:',sum(e['instructions'] for e in entries))
